type ForkliftLogEntry struct {
	Level  string                 `json:"level"`
	Ts     string                 `json:"ts"`
	Logger string                 `json:"logger"`
	Msg    string                 `json:"msg"`
	Fields map[string]interface{} `json:"-"`
}

func (f *ForkliftLogEntry) UnmarshalJSON(data []byte) error {
	type Alias ForkliftLogEntry
	aux := &struct {
		*Alias
	}{
		Alias: (*Alias)(f),
	}
	if err := json.Unmarshal(data, aux); err != nil {
		return err
	}

	// Unmarshal into map to get all fields
	var allFields map[string]interface{}
	if err := json.Unmarshal(data, &allFields); err != nil {
		return err
	}
	f.Fields = allFields
	return nil
}

